import sys

class Main:

	def __init__(self):
		self.buff = None
		self.index = 0

	def next(self):
		if self.buff is None or self.index == len(self.buff):
			self.buff = sys.stdin.readline().split()
			self.index = 0
		val = self.buff[self.index]
		self.index += 1
		return val

	def next_int(self):
		return int(self.next())

	def q(self, a, b, c):
		print(1, c - b + 1, a, ' '.join([str(x) for x in range(b, c + 1)]))
		sys.stdout.flush()
		return self.next_int()

	def a(self, a, n):
		print(1, n - 1, a, ' '.join([str(x) for x in filter(lambda x: x != a, range(1, n + 1))]))
		sys.stdout.flush()
		return self.next_int()

	def solve(self):
		for _ in range(0, self.next_int()):
			n = self.next_int()
			d1 = self.q(1, 2, n)
			low = 2
			high = n
			while high > low:
				mid = (low + high) // 2
				d2 = self.q(1, low, mid)
				if d2 == d1:
					high = mid
				else:
					low = mid + 1
			dd = self.a(low, n)
			print(-1, dd)
			sys.stdout.flush()
Main().solve()
